#include <iostream>

struct Box
{
    int* data;
    int size;
};

Box CopyBox(const Box& original);

int main()
{
    int n;
    while (std::cin >> n)
    {
        int* values = new int[n];
        for (int i = 0; i < n; i++)
        {
            std::cin >> values[i];
        }
        Box original{values, n};

        Box copy = CopyBox(original);

        // Mutate every element reachable through the copy. If CopyBox
        // aliased original's array instead of allocating its own, this
        // mutates original too.
        for (int i = 0; i < copy.size; i++)
        {
            copy.data[i] = copy.data[i] * 10 + 1;
        }

        for (int i = 0; i < original.size; i++)
        {
            std::cout << original.data[i] << (i + 1 < original.size ? " " : "");
        }
        std::cout << "\n";
        for (int i = 0; i < copy.size; i++)
        {
            std::cout << copy.data[i] << (i + 1 < copy.size ? " " : "");
        }
        std::cout << "\n";
    }
    return 0;
}

