"""Random-length boxes of random values, including an empty one."""


def generate(rng, count):
    return [_case(rng, i + 1) for i in range(count)]


def _case(rng, index):
    n = rng.randint(0, 10)
    values = [rng.randint(-50, 50) for _ in range(n)]
    lines = [str(n)] + [str(v) for v in values]
    return {"name": "a box of %d elements #%d" % (n, index),
            "stdin": " ".join(lines) + "\n"}
